describe('parseSheetRows', () => {
  // Test data: anonymized real-world patterns from Express Line sheet

  test('should detect header row and map columns', () => {
    const rows = [
      ['INBOND FLIGHT# + ETA', 'DOCUMENT STATUS', 'Flight #', '1st Leg AWB#', '2nd Leg AWB#', 'ULD / LOOSE', 'PCs', 'CW', 'PICKUP FROM', 'READY FOR PICKUP', 'LFD', 'DELIVER TO', 'DEST', 'CUT OFF DATE/TIME', 'DATE & ETD TIME', 'HOLD BG#', 'HOLD BOX#', 'BATTERY YES/NO'],
      ['', 'DOCS IN DRIVE', 'UC-1711', '369-12345678', '045-87654321', 'BUP', '122', '2560', 'WFS', '5/9/2026', '9-May', 'LATAM CAO', 'MVD', '10-May', '5/11/2026', 'NO HOLD', 'NO HOLD', ''],
    ]
    // After modularization, call parseSheetRows(rows)
    // For now, validate the test structure
    expect(rows[0]).toContain('Flight #')
    expect(rows[1][3]).toBe('369-12345678')
  })

  test('should parse continuation rows as additional holds for parent AWB', () => {
    const rows = [
      ['', 'DOCUMENT STATUS', 'Flight #', '1st Leg AWB#', '2nd Leg AWB#', 'ULD / LOOSE', 'PCs', 'CW', 'PICKUP FROM', '', '', '', '', '', '', 'HOLD BG#', 'HOLD BOX#', ''],
      ['', 'DOCS IN DRIVE', 'UC-1617', '369-99780001', '', 'LOOSE', '75', '1960', 'WFS', '', '', '', 'MVD', '', '', 'BG-FIRST', 'BOX-FIRST', ''],
      // Continuation rows: empty AWB, but have hold data
      ['', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'BG-SECOND', 'BOX-SECOND', ''],
      ['', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'BG-THIRD', 'BOX-THIRD', ''],
      // Next AWB
      ['', 'DOCS IN DRIVE', 'UC-1617', '369-99780002', '', 'LOOSE', '81', '1960', 'WFS', '', '', '', 'MVD', '', '', 'NO HOLD', 'NO HOLD', ''],
    ]
    // Expected: AWB 369-99780001 has 3 holds, AWB 369-99780002 has 0 holds
    // This is the critical continuation row pattern that was broken before
    expect(rows[2][3]).toBe('') // No AWB = continuation
    expect(rows[2][15]).toBe('BG-SECOND') // But has hold data
  })

  test('should skip rows without valid AWB format', () => {
    const rows = [
      ['', '', 'Flight #', '1st Leg AWB#', '', '', 'PCs', 'CW', '', '', '', '', '', '', '', 'HOLD BG#', 'HOLD BOX#', ''],
      ['', '', 'UC-100', 'INVALID-AWB', '', 'LOOSE', '10', '100', '', '', '', '', '', '', '', '', '', ''],
      ['', '', 'UC-100', '369-12345678', '', 'LOOSE', '50', '500', '', '', '', '', '', '', '', '', '', ''],
    ]
    // Only 369-12345678 should be parsed (matches \d{3}-\d+ pattern)
    expect('369-12345678').toMatch(/\d{3}-\d+/)
    expect('INVALID-AWB').not.toMatch(/\d{3}-\d+/)
  })

  test('should handle "NO HOLD" and "pending" hold values correctly', () => {
    const holdValues = [
      { input: 'NO HOLD', expected: 'no_hold' },
      { input: 'no hold', expected: 'no_hold' },
      { input: 'No', expected: 'no_hold' },
      { input: 'N/A', expected: 'no_hold' },
      { input: '', expected: 'no_hold' },
      { input: 'pending', expected: 'pending' },
      { input: 'Pendiente', expected: 'pending' },
      { input: 'BG-2605118F0CZAC0LA', expected: 'hold' },
    ]
    for (const { input, expected } of holdValues) {
      const lower = (input || '').toLowerCase().trim()
      const result = !lower || lower === 'no hold' || lower === 'no' || lower === 'n/a'
        ? 'no_hold'
        : lower === 'pending' || lower === 'pendiente'
          ? 'pending'
          : 'hold'
      expect(result).toBe(expected)
    }
  })
})

describe('computeDiffs', () => {
  test('should detect Hold status change from NO HOLD to HOLD', () => {
    const ex = { holdBg: 'BG-123', holdBox: 'BOX-456', holds: [{ bag: 'BG-123', box: 'BOX-456' }] }
    const sys = { holdStatus: 'NO HOLD', holds: [] }
    // computeDiffs should produce { field: 'Hold', new_value: 'HOLD', old_value: 'NO HOLD' }
    const exHoldLower = (ex.holdBg || '').toLowerCase().trim()
    const exHoldStatus = (!exHoldLower || exHoldLower === 'no hold') ? 'NO HOLD' : 'HOLD'
    expect(exHoldStatus).toBe('HOLD')
    expect(sys.holdStatus).toBe('NO HOLD')
  })

  test('should detect Holds array change when both sides are HOLD', () => {
    const ex = { holds: [{ bag: 'BG-1', box: 'BOX-1' }, { bag: 'BG-2', box: 'BOX-2' }] }
    const sys = { holds: [{ bag: 'hold', box: 'hold' }] }
    const exHolds = ex.holds.map(h => `${h.bag}|${h.box}`).sort().join(';;')
    const sysHolds = sys.holds.map(h => `${h.bag}|${h.box}`).sort().join(';;')
    expect(exHolds).not.toBe(sysHolds) // Should generate Holds diff
  })

  test('should NOT generate diff when holds are identical', () => {
    const holds = [{ bag: 'BG-1', box: 'BOX-1' }, { bag: 'BG-2', box: 'BOX-2' }]
    const exHolds = holds.map(h => `${h.bag}|${h.box}`).sort().join(';;')
    const sysHolds = holds.map(h => `${h.bag}|${h.box}`).sort().join(';;')
    expect(exHolds).toBe(sysHolds) // No diff
  })
})
